          await core.queueRecordingTranscriptions();
        } catch (queueError) {
          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
        }
      } else if (mode === "native") {
        try {
          await core.queueProviderTranscriptions(nativeTranscriptionProvider);
        } catch (queueError) {
          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
        }
      }
      if (interrupted) {
        detail = `Recording was interrupted; ${detail.toLowerCase()}`;
      }
      showStatus({ kind: "success", text: detail });
      void useNotesStore.getState().refresh();
    } catch (err) {
      showStatus({ kind: "error", text: getErrorMessage(err) });
    } finally {
      startPromise.current = null;
      recordingStartedAt.current = null;
      endRecordingActivity();
      setBusy(false);
      // Leave the play-and-record session and drop the background hold so
      // playback routes normally again.
      void setAudioModeAsync({
        allowsRecording: false,
        playsInSilentMode: true,
        shouldPlayInBackground: false,
      }).catch(() => {});
      // Last: releasing this flag may let App.tsx apply a deferred app lock,
      // which unmounts this component.
      useRecordingSessionStore.getState().setActive(false);
    }
  };

  const stopAndSave = (interrupted = false): Promise<void> => {
    if (stopPromise.current) {
      return stopPromise.current;
    }
    const operation: Promise<void> = performStopAndSave(interrupted).finally(() => {
      if (stopPromise.current === operation) {
        stopPromise.current = null;
      }
    });
    stopPromise.current = operation;
    return operation;
  };

  const choosePhoto = async (source: "camera" | "library") => {
    setAttachmentMenuOpen(false);
    setBusy(true);
    try {
      const permission =
        source === "camera"
          ? await ImagePicker.requestCameraPermissionsAsync()
          : await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!permission.granted) {
        throw new Error(
          source === "camera"
            ? "Camera permission denied — enable it in system settings."
            : "Photo library permission denied — enable it in system settings."
        );
      }

      const result =
        source === "camera"
          ? await ImagePicker.launchCameraAsync({
              mediaTypes: ["images"],
              base64: true,
              quality: 1,
            })
          : await ImagePicker.launchImageLibraryAsync({
              mediaTypes: ["images"],
              base64: true,
              quality: 1,
              allowsMultipleSelection: false,
            });
      if (result.canceled) {
        return;
      }
      const asset = result.assets[0];
      const imageBase64 =
        asset.base64 ??
        (await FileSystem.readAsStringAsync(asset.uri, { encoding: "base64" }));
      await core.saveHandwritingAttachment({
        image_base64: imageBase64,
        mime_type: asset.mimeType ?? "image/jpeg",
        file_name: asset.fileName ?? undefined,
      });
      useSyncStore.getState().scheduleAutoSync("attachment saved");
      showStatus({ kind: "success", text: "Saved — your desktop will recognize it" });
      void useNotesStore.getState().refresh();
    } catch (err) {
      showStatus({ kind: "error", text: getErrorMessage(err) });
    } finally {
      setBusy(false);
    }
  };

  // Keep the latest stopAndSave reachable from the unmount effect below.
  const stopAndSaveRef = useRef(stopAndSave);
  stopAndSaveRef.current = stopAndSave;
  const recordingRef = useRef(false);
  recordingRef.current = recorderState.isRecording;

  // Calls, Siri, route loss, or another app taking the audio session can stop
  // a recording even though the JS button was never tapped. expo-audio keeps
  // the completed URI; observe the native transition and save it immediately.
  const nativeRecordingObserved = useRef(false);
  useEffect(() => {
    if (recorderState.isRecording) {
      nativeRecordingObserved.current = true;
      return;
    }
    if (
      nativeRecordingObserved.current &&
      recordingStartedAt.current != null &&
      useRecordingSessionStore.getState().active &&
      !stopPromise.current
    ) {
      nativeRecordingObserved.current = false;
      void stopAndSaveRef.current(true).catch(() => {});
    }
  }, [recorderState.isRecording]);

  // Best effort: navigating away (the capture page pops) while recording
  // stops and saves the clip instead of silently dropping it.
  useEffect(
    () => () => {
      if (recordingRef.current || startPromise.current) {
        void stopAndSaveRef.current().catch(() => {});
      }
    },
    []
  );

  // Stopping from the Lock Screen. The Live Activity's Stop button runs a
  // LiveActivityIntent inside this process, which the native module forwards
  // here — save the clip exactly as an in-app stop would.
  useEffect(() => {
    const stopFromLockScreen = () => {
      if (recorder.isRecording || startPromise.current) {
        void stopAndSaveRef.current().catch(() => {});
      }
    };
    const unsubscribe = addRecordingStopListener(stopFromLockScreen);
    // If the app was suspended when Stop was tapped, the live event never
    // arrived; honor the durable flag the intent left as soon as we're active.
    const appStateSub = AppState.addEventListener("change", (next) => {
      if (next === "active" && consumePendingRecordingStop()) {
        stopFromLockScreen();
      }
    });
    return () => {
      unsubscribe();
      appStateSub.remove();
    };
  }, [recorder]);

  // Read recorder.isRecording (a live native property) instead of the polled
  // recorderState so quick start/stop taps cannot observe stale state.
fn queue_recordings_with_method(
    root: &Path,
    method: &TranscriptionMethod,
) -> Result<RecordingTranscriptionQueueResult, String> {
    let recordings = collect_recording_notes(root)?;
    let active_recordings = active_transcription_note_paths();
    let mut scanned = 0usize;
    let mut skipped = 0usize;
    let mut candidates = Vec::new();

    for recording in recordings {
        scanned += 1;
        if !recording.audio_path.exists() {
            let _ = update_recording_note_status(
                &recording.note_path,
                RECORDING_STATUS_FAILED,
                Some("Audio file is missing.".to_string()),
                None,
                None,
            );
            skipped += 1;
            continue;
        }

        let status = recording.status.as_str();
        let is_active = active_recordings.contains(&recording.note_rel);

        if status == RECORDING_STATUS_COMPLETED {
            skipped += 1;
            continue;
        }

        if matches!(
            status,
            crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
        ) && is_active
        {
            skipped += 1;
            continue;
        }

        update_recording_note_status(
            &recording.note_path,
            crate::RECORDING_STATUS_QUEUED,
            None,
            None,
            None,
        )?;
        candidates.push(QueuedTranscriptionJob {
            note_rel: recording.note_rel,
            note_path: recording.note_path,
            audio_path: recording.audio_path,
            method: method.clone(),
        });
    }

    let queued = {
        let queue = transcription_queue_state();
        let mut state = queue.lock().expect("transcription queue poisoned");
        let mut added = 0usize;
        for job in candidates {
            if state.known_recordings.contains(&job.note_rel) {
                continue;
            }
            state.known_recordings.insert(job.note_rel.clone());
            state.pending.push_back(job);
            added += 1;
        }
        added
    };

    spawn_transcription_worker_if_needed();
    let in_flight = recording_queue_snapshot().in_flight;

    Ok(RecordingTranscriptionQueueResult {
        scanned,
        queued,
        skipped,
        in_flight,
    })
}

/// Reset a single recording's status and re-queue it with `method`.
pub fn retrigger_single_transcription(
    root: &Path,
    note_rel: &str,
    method: TranscriptionMethod,
) -> Result<(), String> {
    let note_path = root.join(note_rel);
    if !note_path.exists() {
        return Err(format!("Note not found: {}", note_rel));
    }
    let raw = fs::read_to_string(&note_path).map_err(|e| e.to_string())?;
    let (meta, _) = parse_note_front_matter(&raw);
    let info = recording_info_from_note_meta(root, &note_path, note_rel, &meta)
        .ok_or_else(|| format!("Not a recording note: {}", note_rel))?;

    if !info.audio_path.exists() {
        return Err("Audio file is missing.".to_string());
    }

    // Reset status to queued
    update_recording_note_status(&note_path, crate::RECORDING_STATUS_QUEUED, None, None, None)?;

    // Add to queue
    {
        let queue = transcription_queue_state();
        let mut state = queue.lock().expect("transcription queue poisoned");
        // Remove from known so it can be re-queued
        state.known_recordings.remove(note_rel);
        state.known_recordings.insert(note_rel.to_string());
        state.pending.push_back(QueuedTranscriptionJob {
            note_rel: note_rel.to_string(),
            note_path,
            audio_path: info.audio_path,
            method,
        });
    }

    spawn_transcription_worker_if_needed();
    Ok(())
}

