@@ -324,9 +367,7 @@ export const DictationButton = ({
       return;
     }
     if (recorder.isRecording || startPromise.current) {
-      if (recorder.isRecording) {
-        void stopAndSave();
-      }
+      void stopAndSave();
       return;
