   554	/// Map a MIME type to a file extension (defaults to "webm").
   555	pub fn audio_extension_from_mime(mime_type: Option<&str>) -> &'static str {
   556	    let Some(raw) = mime_type else {
   557	        return "webm";
   558	    };
   559	    let normalized = raw.to_lowercase();
   560	    if normalized.contains("mp4") || normalized.contains("aac") {
   561	        return "m4a";
   562	    }
   563	    if normalized.contains("mpeg") || normalized.contains("mp3") {
   564	        return "mp3";
   565	    }
   566	    if normalized.contains("wav") {
   567	        return "wav";
   568	    }
   569	    if normalized.contains("ogg") {
   570	        return "ogg";
   571	    }
   572	    if normalized.contains("flac") {
   573	        return "flac";
   574	    }
   575	    "webm"
   576	}
