   578	/// Reject an interrupted MP4/M4A recording before it is persisted and synced.
   579	/// Apple recorders finalize the container by writing a top-level `moov` atom;
   580	/// without it the media bytes cannot be decoded or repaired by Whisper.
   581	fn validate_audio_payload(bytes: &[u8], extension: &str) -> Result<(), String> {
   582	    if !matches!(extension, "m4a" | "mp4") {
   583	        return Ok(());
   584	    }
   585	
   586	    let mut offset = 0usize;
   587	    let mut has_ftyp = false;
   588	    let mut has_moov = false;
   589	
   590	    while bytes.len().saturating_sub(offset) >= 8 {
   591	        let size32 = u32::from_be_bytes(
   592	            bytes[offset..offset + 4]
   593	                .try_into()
   594	                .expect("slice has four bytes"),
   595	        ) as usize;
   596	        let atom_type = &bytes[offset + 4..offset + 8];
   597	        let (header_len, atom_len) = if size32 == 1 {
   598	            if bytes.len().saturating_sub(offset) < 16 {
   599	                break;
   600	            }
   601	            let extended = u64::from_be_bytes(
   602	                bytes[offset + 8..offset + 16]
   603	                    .try_into()
   604	                    .expect("slice has eight bytes"),
   605	            );
   606	            let Ok(atom_len) = usize::try_from(extended) else {
   607	                break;
   608	            };
   609	            (16usize, atom_len)
   610	        } else if size32 == 0 {
   611	            (8usize, bytes.len() - offset)
   612	        } else {
   613	            (8usize, size32)
   614	        };
   615	
   616	        if atom_len < header_len || atom_len > bytes.len() - offset {
   617	            break;
   618	        }
   619	        has_ftyp |= atom_type == b"ftyp";
   620	        has_moov |= atom_type == b"moov";
   621	        if has_ftyp && has_moov {
   622	            return Ok(());
   623	        }
   624	        offset += atom_len;
   625	    }
   626	
   627	    Err("Audio recording is incomplete or invalid (missing M4A metadata).".to_string())
   628	}
