  1024	/// Decide whether a recording discovered by a bulk/automatic scan should be
  1025	/// queued. Failed recordings remain terminal until the user explicitly asks
  1026	/// for a retry through `retrigger_single_transcription`; otherwise the desktop
  1027	/// auto-queue timer would retry a permanently malformed audio file forever.
  1028	fn should_auto_queue_recording(status: &str, is_active: bool) -> bool {
  1029	    if matches!(status, RECORDING_STATUS_COMPLETED | RECORDING_STATUS_FAILED) {
  1030	        return false;
  1031	    }
  1032	
  1033	    !(matches!(
  1034	        status,
  1035	        crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
  1036	    ) && is_active)
  1037	}
