  1039	/// Reset a single recording's status and re-queue it with `method`.
  1040	pub fn retrigger_single_transcription(
  1041	    root: &Path,
  1042	    note_rel: &str,
  1043	    method: TranscriptionMethod,
  1044	) -> Result<(), String> {
  1045	    let note_path = root.join(note_rel);
  1046	    if !note_path.exists() {
  1047	        return Err(format!("Note not found: {}", note_rel));
  1048	    }
  1049	    let raw = fs::read_to_string(&note_path).map_err(|e| e.to_string())?;
  1050	    let (meta, _) = parse_note_front_matter(&raw);
  1051	    let info = recording_info_from_note_meta(root, &note_path, note_rel, &meta)
  1052	        .ok_or_else(|| format!("Not a recording note: {}", note_rel))?;
  1053	
  1054	    if !info.audio_path.exists() {
  1055	        return Err("Audio file is missing.".to_string());
  1056	    }
  1057	
  1058	    // Reset status to queued
  1059	    update_recording_note_status(&note_path, crate::RECORDING_STATUS_QUEUED, None, None, None)?;
  1060	
  1061	    // Add to queue
  1062	    {
  1063	        let queue = transcription_queue_state();
  1064	        let mut state = queue.lock().expect("transcription queue poisoned");
  1065	        // Remove from known so it can be re-queued
  1066	        state.known_recordings.remove(note_rel);
  1067	        state.known_recordings.insert(note_rel.to_string());
  1068	        state.pending.push_back(QueuedTranscriptionJob {
  1069	            note_rel: note_rel.to_string(),
  1070	            note_path,
  1071	            audio_path: info.audio_path,
  1072	            method,
  1073	        });
  1074	    }
  1075	
  1076	    spawn_transcription_worker_if_needed();
  1077	    Ok(())
  1078	}
